import json
from collections import Counter

def transform(grid):
    """Fill interior of rectangular frames with 4"""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Background is most frequent value
    bg = Counter(val for row in grid for val in row).most_common(1)[0][0]

    # Find all non-background cells
    frame_cells = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                frame_cells.append((r, c))

    if not frame_cells:
        return grid

    # Group cells into rectangular frames
    # Approach: find rectangles that bound connected non-bg cells
    # with a gap inside (interior)

    # First, find all rectangular bounding boxes of non-background cells
    # Then check if they form hollow rectangles

    # Create a 2D array marking non-background cells
    is_fg = [[grid[r][c] != bg for c in range(cols)] for r in range(rows)]

    # Find all maximal rectangular regions of non-bg cells
    # We can iterate over all possible rectangles

    filled_interiors = set()

    # For each non-background color, find rectangles
    colors = set(grid[r][c] for r in range(rows) for c in range(cols) if grid[r][c] != bg)

    for color in colors:
        # Find all positions of this color
        cells = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == color]

        # For each connected group of these cells, find the bounding box
        # But we need to be careful - the vertical line connects everything

        # Let's try a different approach: look for rectangles where:
        # 1. Top row is all color
        # 2. Bottom row is all color  \
        # 3. Left column is all color
        # 4. Right column is all color
        # 5. Interior may have holes or be background

        # Find min/max r and c for each color
        if not cells:
            continue

        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)

        # Now check if this bounding box could contain multiple frames

        # For this color, the union of all cells has bounding box [min_r, max_r] x [min_c, max_c]
        # But this could span multiple rectangles
        # Let's use the demo as a hint - frames don't interconnect

        # Try to find rectangles by looking for solid rows and columns
        for top_r in range(min_r, max_r + 1):
            for bottom_r in range(top_r, max_r + 1):
                for left_c in range(min_c, max_c + 1):
                    for right_c in range(left_c, max_c + 1):
                        # Check if this is a valid frame
                        if right_c - left_c < 2 or bottom_r - top_r < 2:
                            continue

                        is_frame = True

                        # Top and bottom rows must be all color (within the bounding box)
                        for c in range(left_c, right_c + 1):
                            if grid[top_r][c] != color:
                                is_frame = False
                                break
                        if not is_frame:
                            continue
                            # Bottom
                        for c in range(left_c, right_c + 1):
                            if grid[bottom_r][c] != color:
                                is_frame = False
                                break
                        if not is_frame:
                            continue

                        # Left and right columns must be all color
                        for r in range(top_r, bottom_r + 1):
                            if grid[r][left_c] != color:
                                is_frame = False
                                break
                        if not is_frame:
                            continue
                            # Right (already checked)
                        for r in range(top_r, bottom_r + 1):
                            if grid[r][right_c] != color:
                                is_frame = False
                                break
                        if not is_frame:
                            continue
                        for r in range(top_r + 1, bottom_r):
                            if grid[r][left_c] != color:
                                is_frame = False
                                break
                        if not is_frame:
                            continue
                            # Interior: should be all background
                        for r in range(top_r + 1, bottom_r):
                            for c in range(left_c + 1, right_c):
                                if grid[r][c] != bg:
                                    is_frame = False
                                    break
                            if not is_frame:
                                break
                        if not is_frame:
                            continue

                        # Valid frame, mark interior for filling
                        for r in range(top_r + 1, bottom_r):
                            for c in range(left_c + 1, right_c):
                                filled_interiors.add((r, c))

    # Apply fills
    result = [row[:] for row in grid]
    for r, c in sorted(filled_interiors, reverse=True):
        result[r][c] = 4

    return result

